const config = $('Configure health check').first().json;
const now = new Date().toISOString();
const runId = 'wazuh-health-' + Date.now();
const deploymentAliases = { baremetal: 'on-premises', 'bare-metal': 'on-premises', onprem: 'on-premises', vm: 'virtual-machine', container: 'docker', containers: 'docker', k8s: 'kubernetes' };
const requestedDeploymentType = String(config.deploymentType ?? 'on-premises').trim().toLowerCase();
const deploymentType = deploymentAliases[requestedDeploymentType] ?? requestedDeploymentType;
const supportedDeploymentTypes = new Set(['on-premises', 'virtual-machine', 'docker', 'kubernetes']);

const valueOf = (name) => {
  const item = $(name).first()?.json ?? {};
  return item;
};
const affected = (name) => valueOf(name)?.data?.affected_items ?? [];
const checks = [];
const add = (id, component, status, value, threshold, recommendation, evidence = '') => {
  checks.push({ id, component, status, value, threshold, recommendation, evidence });
};
const numeric = (value, fallback = 0) => {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
};
const statusForPercent = (value, warning, critical) => value >= critical ? 'Critical' : value >= warning ? 'Warning' : 'Healthy';
const sumNumericLeaves = (value) => {
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  if (!value || typeof value !== 'object') return 0;
  return Object.values(value).reduce((total, entry) => total + sumNumericLeaves(entry), 0);
};
const formatGiB = (bytes) => (numeric(bytes) / 1073741824).toFixed(1) + ' GiB';

const managerInfo = affected('Get Wazuh manager information')[0] ?? {};
add('manager_api', 'Wazuh Manager', managerInfo.version ? 'Healthy' : 'Critical', managerInfo.version ?? 'Unavailable', 'API reachable', 'Verify Wazuh API availability and credentials.');

const processState = affected('Check Wazuh manager processes')[0] ?? {};
const essentialDaemons = ['wazuh-analysisd', 'wazuh-remoted', 'wazuh-modulesd', 'wazuh-db', 'wazuh-apid'];
const stoppedDaemons = essentialDaemons.filter(name => processState[name] !== 'running');
add('manager_daemons', 'Wazuh Manager', stoppedDaemons.length ? 'Critical' : 'Healthy', stoppedDaemons.length ? stoppedDaemons.join(', ') : 'All essential daemons running', 'All essential daemons running', 'Investigate and restore stopped essential Wazuh processes.', JSON.stringify(processState));

const agentData = valueOf('Summarize Wazuh agent status')?.data?.connection ?? affected('Summarize Wazuh agent status')[0] ?? {};
const activeAgents = numeric(agentData.active);
const disconnectedAgents = numeric(agentData.disconnected);
const pendingAgents = numeric(agentData.pending);
const neverConnectedAgents = numeric(agentData.never_connected ?? agentData.neverConnected);
const totalAgents = numeric(agentData.total, activeAgents + disconnectedAgents + pendingAgents + neverConnectedAgents);
const disconnectedPercent = totalAgents > 0 ? (disconnectedAgents / totalAgents) * 100 : 0;
const agentStatus = totalAgents === 0
  ? 'Unknown'
  : activeAgents === 0
    ? 'Critical'
    : statusForPercent(disconnectedPercent, numeric(config.disconnectedWarningPercent), numeric(config.disconnectedCriticalPercent));
add('agent_connectivity', 'Wazuh Agents', agentStatus, activeAgents + ' active; ' + disconnectedAgents + ' disconnected; ' + pendingAgents + ' pending; ' + neverConnectedAgents + ' never connected (' + disconnectedPercent.toFixed(2) + '% disconnected)', 'Warning ' + config.disconnectedWarningPercent + '% / Critical ' + config.disconnectedCriticalPercent + '% or no active agents', 'Review agent connectivity, endpoint availability, certificates and network paths.', JSON.stringify({ activeAgents, disconnectedAgents, pendingAgents, neverConnectedAgents, totalAgents }));

const analysisd = affected('Collect Wazuh daemon statistics').find(item => item.name === 'wazuh-analysisd') ?? {};
const analysisdMetrics = analysisd.metrics ?? {};
const received = numeric(analysisdMetrics?.events?.received);
const droppedBreakdown = analysisdMetrics?.events?.received_breakdown?.dropped_breakdown ?? {};
const dropped = sumNumericLeaves(droppedBreakdown);
const droppedRate = received > 0 ? (dropped / received) * 100 : dropped > 0 ? 100 : 0;
const droppedStatus = analysisd.name ? statusForPercent(droppedRate, numeric(config.droppedWarningRatePercent), numeric(config.droppedCriticalRatePercent)) : 'Unknown';
add('dropped_events', 'Wazuh Analysis', droppedStatus, analysisd.name ? received + ' received; ' + dropped + ' dropped (' + droppedRate.toFixed(3) + '%)' : 'Analysis daemon metrics unavailable', 'Warning ' + config.droppedWarningRatePercent + '% / Critical ' + config.droppedCriticalRatePercent + '%', 'Correlate EPS, CPU, memory, storage and integration behavior to identify ingestion bottlenecks.', JSON.stringify(analysisdMetrics));

const managerCluster = affected('Check Wazuh server cluster');
const clusterDisconnected = managerCluster.filter(node => ['disconnected', 'failed'].includes(String(node.status ?? '').toLowerCase()));
const managerClusterValue = managerCluster.length
  ? (clusterDisconnected.length ? clusterDisconnected.length + ' unhealthy node(s)' : managerCluster.length + ' node(s) connected')
  : 'Single-node deployment; manager cluster not enabled';
add('manager_cluster', 'Wazuh Server Cluster', clusterDisconnected.length ? 'Critical' : 'Healthy', managerClusterValue, 'All configured nodes connected; not applicable for single-node', 'Review Wazuh server cluster synchronization and node connectivity.', JSON.stringify(managerCluster));

const indexer = valueOf('Check Wazuh indexer cluster health');
const indexerStatus = String(indexer.status ?? 'unknown').toLowerCase();
const indexerAvailable = !indexer.error && ['green', 'yellow', 'red'].includes(indexerStatus);
const indexerSeverity = !indexerAvailable ? 'Unknown' : indexerStatus === 'red' ? 'Critical' : indexerStatus === 'yellow' ? 'Warning' : 'Healthy';
const indexerErrorStatus = indexer?.error?.status ?? indexer?.error?.statusCode ?? 'unavailable';
add(
  'indexer_cluster',
  'Wazuh Indexer',
  indexerSeverity,
  indexerAvailable
    ? indexerStatus + '; nodes ' + numeric(indexer.number_of_nodes) + '; data nodes ' + numeric(indexer.number_of_data_nodes)
    : 'Cluster health unavailable (HTTP ' + indexerErrorStatus + ')',
  'Green preferred; Yellow requires topology review; Red is critical',
  indexerAvailable
    ? 'Review unassigned shards, replicas, allocation rules and indexer node availability.'
    : 'Grant the read-only cluster_monitor action group and verify the Indexer credential.',
  JSON.stringify(indexer),
);
add(
  'indexer_shards',
  'Wazuh Indexer',
  indexerSeverity,
  indexerAvailable
    ? 'Active primary: ' + numeric(indexer.active_primary_shards) +
      '; active total: ' + numeric(indexer.active_shards) +
      '; unassigned: ' + numeric(indexer.unassigned_shards) +
      '; initializing: ' + numeric(indexer.initializing_shards) +
      '; relocating: ' + numeric(indexer.relocating_shards) +
      '; active: ' + numeric(indexer.active_shards_percent_as_number).toFixed(2) + '%'
    : 'Shard allocation unavailable',
  'No unassigned primary shards; investigate replicas when status is Yellow',
  indexerAvailable
    ? 'Investigate unassigned primary shards immediately; review replica allocation in the context of the cluster topology.'
    : 'Restore read-only cluster health access before evaluating shard allocation.',
  JSON.stringify(indexer),
);

const allocations = Array.isArray(valueOf('Collect indexer storage allocation')) ? valueOf('Collect indexer storage allocation') : $('Collect indexer storage allocation').all().map(i => i.json);
const validAllocations = allocations.filter(row => !row.error && (row['disk.percent'] != null || row.disk_percent != null));
const allocationAvailable = validAllocations.length > 0;
const maxIndexerDisk = allocationAvailable ? Math.max(...validAllocations.map(row => numeric(row['disk.percent'] ?? row.disk_percent))) : null;
add('indexer_storage', 'Wazuh Indexer', allocationAvailable ? statusForPercent(maxIndexerDisk, numeric(config.diskWarningPercent), numeric(config.diskCriticalPercent)) : 'Unknown', allocationAvailable ? maxIndexerDisk.toFixed(1) + '%' : 'Storage allocation unavailable', 'Warning ' + config.diskWarningPercent + '% / Critical ' + config.diskCriticalPercent + '%', allocationAvailable ? 'Review ISM retention, index growth, shard sizing and available capacity.' : 'Grant read-only cluster monitoring permission and retry the collection.', JSON.stringify(allocations));

const indexerNodes = $('Collect indexer node pressure').all().map(i => i.json);
const validIndexerNodes = indexerNodes.filter(row => !row.error && (row['heap.percent'] != null || row.heap_percent != null));
const indexerNodesAvailable = validIndexerNodes.length > 0;
const maxHeap = indexerNodesAvailable ? Math.max(...validIndexerNodes.map(row => numeric(row['heap.percent'] ?? row.heap_percent))) : null;
add('indexer_heap', 'Wazuh Indexer', indexerNodesAvailable ? statusForPercent(maxHeap, numeric(config.heapWarningPercent), numeric(config.heapCriticalPercent)) : 'Unknown', indexerNodesAvailable ? maxHeap.toFixed(1) + '%' : 'Node pressure unavailable', 'Warning ' + config.heapWarningPercent + '% / Critical ' + config.heapCriticalPercent + '%', indexerNodesAvailable ? 'Review JVM pressure, query load, shard count and available indexer memory.' : 'Grant read-only cluster monitoring permission and retry the collection.', JSON.stringify(indexerNodes));

const hostResult = valueOf('Collect host and runtime metrics');
const hostValues = {};
const containers = [];
for (const rawLine of String(hostResult.stdout ?? '').split(String.fromCharCode(10))) {
  const line = rawLine.replace(String.fromCharCode(13), '');
  if (line.startsWith('CONTAINER=')) {
    const [name, state, health, restarts] = line.slice(10).split('|');
    containers.push({ name, state, health, restarts: numeric(restarts) });
  } else {
    const index = line.indexOf('=');
    if (index > 0) hostValues[line.slice(0, index)] = line.slice(index + 1);
  }
}
const hostMetricsAvailable = Object.keys(hostValues).length > 0;
const runtimeType = String(hostValues.RUNTIME_TYPE ?? 'none').toLowerCase();
const cpuUsed = numeric(hostValues.CPU_USED_PERCENT);
const cpuCores = numeric(hostValues.CPU_CORES);
const load1m = numeric(hostValues.LOAD_1M);
const memoryTotal = numeric(hostValues.MEM_TOTAL);
const memoryAvailable = numeric(hostValues.MEM_AVAILABLE);
const memoryUsedPercent = memoryTotal > 0 ? ((memoryTotal - memoryAvailable) / memoryTotal) * 100 : 0;
const swapTotal = numeric(hostValues.SWAP_TOTAL);
const swapUsed = numeric(hostValues.SWAP_USED);
const rootTotal = numeric(hostValues.ROOT_TOTAL);
const rootAvailable = numeric(hostValues.ROOT_AVAILABLE);
const rootUsedPercent = numeric(hostValues.ROOT_USED_PERCENT);
const inodeUsedPercent = numeric(hostValues.ROOT_INODE_PERCENT);
const hostEvidence = JSON.stringify({ hostname: hostValues.HOSTNAME, cpuUsed, cpuCores, load1m, memoryTotal, memoryAvailable, swapTotal, swapUsed, rootTotal, rootAvailable, rootUsedPercent, inodeUsedPercent });
add('host_cpu', 'Host Infrastructure', hostMetricsAvailable ? statusForPercent(cpuUsed, numeric(config.cpuWarningPercent), numeric(config.cpuCriticalPercent)) : 'Unknown', hostMetricsAvailable ? cpuUsed.toFixed(1) + '% used; load ' + load1m.toFixed(2) + ' / ' + cpuCores + ' cores (point-in-time sample)' : 'Host metrics unavailable', 'Warning ' + config.cpuWarningPercent + '% / Critical ' + config.cpuCriticalPercent + '%', 'Review sustained CPU consumption, EPS volume and container-level usage.', hostEvidence);
add('host_memory', 'Host Infrastructure', hostMetricsAvailable && memoryTotal > 0 ? statusForPercent(memoryUsedPercent, numeric(config.memoryWarningPercent), numeric(config.memoryCriticalPercent)) : 'Unknown', hostMetricsAvailable && memoryTotal > 0 ? memoryUsedPercent.toFixed(1) + '% used; ' + formatGiB(memoryAvailable) + ' available of ' + formatGiB(memoryTotal) + '; swap ' + formatGiB(swapUsed) + ' used of ' + formatGiB(swapTotal) : 'Memory metrics unavailable', 'Warning ' + config.memoryWarningPercent + '% / Critical ' + config.memoryCriticalPercent + '%', 'Review memory pressure, swap activity and indexer heap allocation.', hostEvidence);
add('host_storage', 'Host Infrastructure', hostMetricsAvailable && rootTotal > 0 ? statusForPercent(rootUsedPercent, numeric(config.diskWarningPercent), numeric(config.diskCriticalPercent)) : 'Unknown', hostMetricsAvailable && rootTotal > 0 ? rootUsedPercent.toFixed(1) + '% used; ' + formatGiB(rootAvailable) + ' available of ' + formatGiB(rootTotal) : 'Storage metrics unavailable', 'Warning ' + config.diskWarningPercent + '% / Critical ' + config.diskCriticalPercent + '%', 'Review Wazuh data paths, index retention and historical storage growth for the selected deployment architecture.', hostEvidence);
add('host_inodes', 'Host Infrastructure', hostMetricsAvailable ? statusForPercent(inodeUsedPercent, 75, 90) : 'Unknown', hostMetricsAvailable ? inodeUsedPercent.toFixed(1) + '% used' : 'Inode metrics unavailable', 'Warning 75% / Critical 90%', 'Locate directories creating excessive numbers of small files.', hostEvidence);
const unhealthyContainers = containers.filter(container => container.state !== 'running' || !['healthy', 'none'].includes(container.health) || container.restarts > 5);
if (deploymentType === 'docker') {
  add('container_health', 'Deployment Runtime', runtimeType === 'docker' && containers.length ? (unhealthyContainers.length ? 'Critical' : 'Healthy') : 'Unknown', runtimeType === 'docker' && containers.length ? (unhealthyContainers.length ? unhealthyContainers.map(c => c.name).join(', ') : containers.length + ' container(s) running; no unhealthy containers') : 'Docker runtime or container metrics unavailable', 'Docker available; containers running; health healthy/none; restarts <= 5', 'Inspect unhealthy containers, recent logs, restart causes, and Docker access for the SSH account.', JSON.stringify({ deploymentType, runtimeType, containers }));
} else if (deploymentType === 'kubernetes') {
  add('container_health', 'Deployment Runtime', 'Unknown', 'Kubernetes workload health is not collected by the SSH baseline', 'Kubernetes API plus node and pod metrics required', 'Add authenticated Kubernetes API, metrics-server, or Prometheus collection for node, pod, restart, and persistent-volume health.', JSON.stringify({ deploymentType, runtimeType }));
} else if (['on-premises', 'virtual-machine'].includes(deploymentType)) {
  add('container_health', 'Deployment Runtime', 'Healthy', 'Not applicable for ' + deploymentType, 'No container runtime check required', 'No runtime action required; retain the host, Wazuh API, and Indexer checks.', JSON.stringify({ deploymentType, runtimeType }));
} else {
  add('container_health', 'Deployment Runtime', 'Unknown', 'Unsupported deploymentType: ' + deploymentType, 'Use on-premises, virtual-machine, docker, or kubernetes', 'Correct deploymentType in Configure health check before interpreting the assessment.', JSON.stringify({ deploymentType, runtimeType }));
}

const criticalCount = checks.filter(check => check.status === 'Critical').length;
const warningCount = checks.filter(check => check.status === 'Warning').length;
const unknownCount = checks.filter(check => check.status === 'Unknown').length;
const greenCount = checks.filter(check => check.status === 'Healthy').length;
const verifiedCount = Math.max(1, checks.length - unknownCount);
const greenPercent = (greenCount / verifiedCount) * 100;
const yellowPercent = (warningCount / verifiedCount) * 100;
const redPercent = (criticalCount / verifiedCount) * 100;
const coreChecks = new Set(['manager_api', 'manager_daemons', 'agent_connectivity', 'dropped_events', 'indexer_cluster', 'indexer_shards', 'host_cpu', 'host_memory', 'host_storage', 'container_health']);
const hasCoreRed = checks.some(check => check.status === 'Critical' && coreChecks.has(check.id));
const overallStatus = hasCoreRed || redPercent >= 20
  ? 'Red'
  : unknownCount > 0 || greenPercent < 80 || yellowPercent >= 20
    ? 'Yellow'
    : 'Green';
const checkWeights = {
  manager_api: 10,
  manager_daemons: 12,
  agent_connectivity: 8,
  dropped_events: 12,
  manager_cluster: 5,
  indexer_cluster: 10,
  indexer_shards: 10,
  indexer_storage: 8,
  indexer_heap: 5,
  host_cpu: 5,
  host_memory: 5,
  host_storage: 5,
  host_inodes: 2,
  container_health: 3,
};
const statusFactors = { Healthy: 1, Warning: 0.5, Critical: 0, Unknown: 0.25 };
const healthScore = Math.round(checks.reduce((score, check) => score + numeric(checkWeights[check.id]) * numeric(statusFactors[check.status]), 0));

const recommendations = [];
const addRecommendation = (priority, title, reason, action) => recommendations.push({ priority, title, reason, action });
if (rootUsedPercent >= numeric(config.diskWarningPercent) || (allocationAvailable && maxIndexerDisk >= numeric(config.diskWarningPercent))) {
  addRecommendation(rootUsedPercent >= numeric(config.diskCriticalPercent) || (allocationAvailable && maxIndexerDisk >= numeric(config.diskCriticalPercent)) ? 'Critical' : 'High', 'Review Wazuh index lifecycle and retention', 'Storage consumption is approaching or exceeding the configured threshold.', 'Validate ISM policies, retention requirements, index growth, rollover and available capacity.');
}
if (dropped > 0 && (cpuUsed >= numeric(config.cpuWarningPercent) || memoryUsedPercent >= numeric(config.memoryWarningPercent))) {
  addRecommendation('Critical', 'Investigate capacity-driven event loss', 'Dropped events coincide with host resource pressure.', 'Correlate EPS peaks with CPU, memory and analysis daemon statistics; resize or tune the environment before increasing ingestion.');
} else if (dropped > 0) {
  addRecommendation('High', 'Review ingestion and integration configuration', 'Events are being dropped without clear host resource saturation.', 'Inspect recent integrations, decoder/rule load, queue utilization and unexpected EPS sources.');
}
if (!indexerAvailable) {
  addRecommendation('High', 'Restore Indexer health visibility', 'The read-only account could not retrieve cluster health and shard allocation.', 'Grant the cluster_monitor action group, verify the role mapping, and repeat the health check.');
} else if (indexerStatus === 'yellow' || indexerStatus === 'red' || numeric(indexer.unassigned_shards) > 0) {
  addRecommendation(indexerStatus === 'red' ? 'Critical' : 'High', 'Resolve indexer shard allocation', 'The indexer cluster is not fully allocated.', 'Review replica count, single-node topology, disk watermarks and allocation explanations before changing shard settings.');
}
if (disconnectedPercent >= numeric(config.disconnectedWarningPercent)) {
  addRecommendation(agentStatus === 'Critical' ? 'Critical' : 'Medium', 'Investigate disconnected Wazuh agents', 'The disconnected-agent ratio exceeds the configured environment threshold.', 'Segment the affected agents by network, operating system and last keepalive to identify a common cause.');
}
if (deploymentType === 'docker' && unhealthyContainers.length) {
  addRecommendation('Critical', 'Restore unhealthy containers', 'One or more platform containers are stopped, unhealthy or repeatedly restarting.', 'Review container logs, health checks, resource limits and dependent services.');
}
if (deploymentType === 'kubernetes') {
  addRecommendation('High', 'Connect Kubernetes workload telemetry', 'The generic SSH baseline cannot verify Kubernetes node, pod, restart, and persistent-volume health.', 'Add a least-privilege Kubernetes API, metrics-server, or Prometheus integration, then map its evidence into the deployment runtime check.');
}
if (!supportedDeploymentTypes.has(deploymentType)) {
  addRecommendation('High', 'Correct the deployment profile', 'The configured deploymentType is not supported.', 'Set deploymentType to on-premises, virtual-machine, docker, or kubernetes and run the assessment again.');
}
if (!recommendations.length) addRecommendation('Informational', 'Maintain the current operating baseline', 'No threshold violations were detected.', 'Store this run as a reference and execute the workflow again after significant integrations, upgrades or configuration changes.');

let previous = $input.first()?.json ?? {};
let previousMetrics = {};
try { previousMetrics = JSON.parse(previous.metrics_object || '{}'); } catch {}
const comparison = previous.runId ? {
  previousRunId: previous.runId,
  previousRunAt: previous.runAt ?? previous.createdAt ?? null,
  previousStatus: previous.overallStatus ?? null,
  previousScore: numeric(previous.healthScore, null),
  scoreChange: previous.healthScore == null ? null : healthScore - numeric(previous.healthScore),
  statusChanged: previous.overallStatus !== overallStatus,
  previousMetricsAvailable: Object.keys(previousMetrics).length > 0,
} : { baselineCreated: true };

const escapeHtml = value => String(value ?? '')
  .replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;')
  .replaceAll('"', '&quot;').replaceAll("'", '&#039;');
const statusColor = status => ({ Green: '#15803d', Yellow: '#b45309', Red: '#b91c1c', Healthy: '#15803d', Warning: '#b45309', Critical: '#b91c1c', Unknown: '#475569' }[status] ?? '#475569');
const checkRows = checks.map(check => '<tr>' +
  '<td style="padding:8px;border-bottom:1px solid #e5e7eb">' + escapeHtml(check.component) + '</td>' +
  '<td style="padding:8px;border-bottom:1px solid #e5e7eb">' + escapeHtml(check.id) + '</td>' +
  '<td style="padding:8px;border-bottom:1px solid #e5e7eb;color:' + statusColor(check.status) + ';font-weight:700">' + escapeHtml(check.status) + '</td>' +
  '<td style="padding:8px;border-bottom:1px solid #e5e7eb">' + escapeHtml(check.value) + '</td>' +
  '<td style="padding:8px;border-bottom:1px solid #e5e7eb">' + escapeHtml(check.recommendation) + '</td>' +
  '</tr>').join('');
const recommendationRows = recommendations.map(item => '<li style="margin-bottom:12px"><strong>' + escapeHtml(item.priority) + ': ' + escapeHtml(item.title) + '</strong><br>' + escapeHtml(item.reason) + '<br><em>Action:</em> ' + escapeHtml(item.action) + '</li>').join('');
const comparisonText = comparison.baselineCreated ? 'This is the first stored baseline.' : 'Previous status: ' + escapeHtml(comparison.previousStatus) + '; score change: ' + (comparison.scoreChange >= 0 ? '+' : '') + comparison.scoreChange + '.';
const htmlReport = '<div style="font-family:Arial,sans-serif;color:#111827;max-width:1000px;margin:auto">' +
  '<div style="background:#111827;color:white;padding:24px;border-radius:10px 10px 0 0"><h1 style="margin:0">Wazuh Platform Health Check</h1><p>' + escapeHtml(config.organizationName) + ' · ' + escapeHtml(now) + '</p></div>' +
  '<div style="padding:24px;border:1px solid #e5e7eb"><h2 style="color:' + statusColor(overallStatus) + '">Overall status: ' + overallStatus + ' · Score: ' + healthScore + '/100</h2>' +
  '<p><strong>Assessment:</strong> ' + escapeHtml(config.assessmentLabel) + '<br><strong>Deployment:</strong> ' + escapeHtml(deploymentType) + '<br><strong>Comparison:</strong> ' + comparisonText + '</p>' +
  '<p><strong>Green checks:</strong> ' + greenCount + ' (' + greenPercent.toFixed(1) + '%) · <strong>Yellow checks:</strong> ' + warningCount + ' (' + yellowPercent.toFixed(1) + '%) · <strong>Red checks:</strong> ' + criticalCount + ' (' + redPercent.toFixed(1) + '%) · <strong>Unverified:</strong> ' + unknownCount + '</p>' +
  '<p style="color:#475569"><strong>Overall rule:</strong> Green when at least 80% of verified checks are green, fewer than 20% are yellow, no core check is red, and no check is unverified. Unverified data produces Yellow because the assessment is incomplete.</p>' +
  '<h2>Prioritized recommendations</h2><ol>' + recommendationRows + '</ol>' +
  '<h2>Technical checks</h2><table style="border-collapse:collapse;width:100%;font-size:13px"><thead><tr style="background:#f3f4f6"><th>Component</th><th>Check</th><th>Status</th><th>Value</th><th>Recommendation</th></tr></thead><tbody>' + checkRows + '</tbody></table>' +
  '<p style="font-size:12px;color:#6b7280;margin-top:24px">Thresholds are configurable. Interpret this report with the environment profile, expected agent count, expected EPS, architecture and retention requirements.</p></div></div>';

return [{ json: {
  runId,
  runAt: now,
  assessmentLabel: config.assessmentLabel,
  deploymentType,
  overallStatus,
  healthScore,
  criticalCount,
  warningCount,
  greenCount,
  unknownCount,
  greenPercent: Number(greenPercent.toFixed(2)),
  yellowPercent: Number(yellowPercent.toFixed(2)),
  redPercent: Number(redPercent.toFixed(2)),
  checks,
  recommendations,
  comparison,
  metrics_object: JSON.stringify({ deploymentType, runtimeType, checks, hostValues, containers, managerInfo, agentData, indexer }),
  recommendations_object: JSON.stringify(recommendations),
  comparison_object: JSON.stringify(comparison),
  emailSubject: '[' + overallStatus.toUpperCase() + '] ' + config.organizationName + ' Wazuh Health Check - ' + now.slice(0, 10),
  htmlReport,
}}];
